def numerical(q,eq,series,term,start,places=None,eps=None):
 N=start;sm=mp.mpf(term(N));tol=mp.mpf(str(eps))if eps is not None else mp.mpf(10)**(-places)/2
 while True:
  nxt=mp.mpf(term(N+1));lo,hi=sorted([sm,sm+nxt])
  if abs(nxt)<tol and (places is None or round(float(lo),places)==round(float(hi),places)):break
  N+=1;sm+=term(N)
 ans=f'{float(sm):.{places}f}'if places is not None else f'{float(sm):.12f}'
 calc(q,eq,'지정한 정확도를 만족하도록 급수로 계산하고 나머지 상계를 제시하라.','Compute by a series to the requested accuracy and give a remainder bound.',[series,rf'\text{{sum through }}n={N}:\quad s={float(sm):.12f}',rf'|R|\le|a_{{{N+1}}}|={float(abs(nxt)):.12f}',rf'{float(lo):.12f}\le S\le{float(hi):.12f}'],rf'S\approx{ans}','사용한 꼬리는 크기가 감소하는 교대급수이다. 두 경계가 요청된 자리까지 동일하게 반올림되거나, 지정 절대오차보다 좁은 구간을 이룬다.','The tail used is alternating with decreasing magnitudes. Its bounds either round alike at the requested precision or enclose an interval narrower than the required absolute error.')
numerical(55,r'\cos5^\circ,\quad d=5',r'5^\circ=\pi/36,\quad\cos(\pi/36)=\sum_{n=0}^\infty(-1)^n(\pi/36)^{2n}/(2n)!',lambda j:(-1)**j*(mp.pi/36)**(2*j)/mp.factorial(2*j),0,places=5)
