 if segment:out.append('<polyline points="'+' '.join(segment)+'" fill="none" stroke="#111827" stroke-width="3" clip-path="url(#view)"/>')
 for z in [xa,0,xb]:out.append(f'<text x="{X(z)-10}" y="390" font-size="12">{z:g}</text>')
