 out.extend(['<text x="65" y="443" font-size="13">Black: function. Colors: partial sums through index N.</text>','</svg>']);path=BASE/f'exercise-content/assets/s11-10-{q}.svg';path.write_text(''.join(out));next(e for e in items if e['number']==q)['figure']={'src':f'../exercise-content/assets/{path.name}','alt':bi('함수와 여러 멱급수 부분합의 비교','Comparison of a function and several power-series partial sums'),'caption':bi('함수식과 계수로 직접 생성한 자체 그래프.','Original plots computed directly from the function and coefficients.')}

